import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The three costs — how the engine knows a form is better","description":"","frontmatter":{},"headers":[],"relativePath":"graphopt/explanation/three-costs.md","filePath":"vendored/graphopt/explanation/three-costs.md"}`),a={name:`graphopt/explanation/three-costs.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-three-costs-—-how-the-engine-knows-a-form-is-better" tabindex="-1">The three costs — how the engine knows a form is <em>better</em> <a class="header-anchor" href="#the-three-costs-—-how-the-engine-knows-a-form-is-better" aria-label="Permalink to “The three costs — how the engine knows a form is better”">​</a></h1><p>&quot;How do you know the cost — and how do you know when it found a better algorithm?&quot; The answer is three different costs at three different trust levels. Each level exists because the cheaper one can lie.</p><h2 id="_1-dag-cost-—-the-guess" tabindex="-1">1. <code>dag_cost</code> — the <em>guess</em> <a class="header-anchor" href="#_1-dag-cost-—-the-guess" aria-label="Permalink to “1. dag_cost — the guess”">​</a></h2><p>The e-graph holds thousands of equivalent forms; extraction picks one. <code>dag_cost</code> walks the program graph and sums static weights — FLOPs per op, parameter bytes, node counts. No tensors ever execute.</p><p><strong>Why it can lie:</strong> it has no notion of memory traffic, kernel fusion, launch overhead, or cache behavior. A fused <code>sdpa</code> call looks expensive on paper but is fast under Inductor. Used for <em>ranking</em>, never for <em>claims</em>.</p><h2 id="_2-measured-pay-—-the-experiment" tabindex="-1">2. Measured pay — the <em>experiment</em> <a class="header-anchor" href="#_2-measured-pay-—-the-experiment" aria-label="Permalink to “2. Measured pay — the experiment”">​</a></h2><p>A minted law cannot ship on <code>dag_cost</code> alone. The admission <a href="./the-gauntlet.html">gauntlet</a> runs the candidate on <strong>real tensors, seeded fixtures</strong> and measures wall time / peak memory. This is where &quot;better&quot; becomes empirical — and where 212 bad accepts died: they <em>looked</em> paying until measured at real sites.</p><p><strong>Why it can still lie:</strong> fixtures are small, seeded, one GPU box — hence &quot;regime-bounded&quot; in the honest scope.</p><h2 id="_3-numerical-verify-—-the-certified-equality" tabindex="-1">3. Numerical verify — the <em>certified equality</em> <a class="header-anchor" href="#_3-numerical-verify-—-the-certified-equality" aria-label="Permalink to “3. Numerical verify — the certified equality”">​</a></h2><p>After lowering, the produced module executes and its outputs are compared against the source&#39;s, fp64-exact where stated. Verification says <strong>the output is identical</strong> — nothing about speed.</p><h2 id="the-composition" tabindex="-1">The composition <a class="header-anchor" href="#the-composition" aria-label="Permalink to “The composition”">​</a></h2><table tabindex="0"><thead><tr><th>level</th><th>answers</th><th>can be wrong because</th></tr></thead><tbody><tr><td><code>dag_cost</code></td><td>&quot;probably cheaper&quot;</td><td>the model misses hardware reality</td></tr><tr><td>measured pay</td><td>&quot;actually cheaper on these fixtures&quot;</td><td>fixtures ≠ all regimes</td></tr><tr><td>verify</td><td>&quot;computes the same thing&quot;</td><td>says nothing about cost</td></tr></tbody></table><p>&quot;Found a better algorithm&quot; = all three: <strong>verified-equal output + measured cheaper + ranked by the model that guided the search.</strong></p><p>The referee separates the same way: <a href="./the-game.html">the game&#39;s</a> value spec (<code>ScoringSpec</code>) <em>declares</em> which axes matter; the gauntlet&#39;s measurement supplies the numbers — the two sides meet only through a plain <code>Mapping[str, float]</code>.</p><p><strong>One-liner:</strong> <em>the model proposes, the fixtures measure, the verifier certifies — a law ships only if all three agree.</em></p>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};